import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';

import { getOneClubAsync } from '../@services/clubs.service';
import { IClub } from '../@types/clubs.types';

interface IOneClubProps {
  id: number;
  onDataReady?: (club: IClub) => void;
}

const OneClub = ({ id, onDataReady }: IOneClubProps) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IClub>();
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = await getOneClubAsync(id);
        setData(d);
        onDataReady?.(d);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err}</PohAlert>;
  }

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  return (
    <article className="text-center">
      <PohAva width={128} src={data.logo} />
      <br />
      <h2>{data.name}</h2>
      <p>{data.description}</p>
    </article>
  );
};

export default OneClub;
